import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"术语词典","description":"","frontmatter":{},"headers":[],"relativePath":"zh/90-术语词典.md","filePath":"zh/90-术语词典.md"}'),o={name:"zh/90-术语词典.md"};function l(i,t,h,n,u,s){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="术语词典" tabindex="-1">术语词典 <a class="header-anchor" href="#术语词典" aria-label="Permalink to &quot;术语词典&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>文档编号</td><td>90</td></tr><tr><td>所属模块</td><td>附录与参考资料</td></tr><tr><td>核心关键词</td><td>术语词典、核心概念、定义、统一术语、衡元宙</td></tr></tbody></table><h2 id="一、术语说明" tabindex="-1">一、术语说明 <a class="header-anchor" href="#一、术语说明" aria-label="Permalink to &quot;一、术语说明&quot;">​</a></h2><p>本词典收录锚点共生文明设定体系中的核心术语，旨在统一全部文档中的术语使用，确保概念表述的一致性与准确性。所有术语均按照汉语拼音首字母排序，每条术语包含术语名称、英文参考名（如有）、定义与简要说明。本词典为动态更新文档，随着设定体系的扩展将持续增补新术语。</p><h2 id="二、核心术语表" tabindex="-1">二、核心术语表 <a class="header-anchor" href="#二、核心术语表" aria-label="Permalink to &quot;二、核心术语表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>序号</th><th>术语</th><th>定义与说明</th></tr></thead><tbody><tr><td>1</td><td>锚点</td><td>法则网络中的稳定节点，是维系位面法则稳定、实现跨位面连接与时间回溯的坐标基准。锚点本质上是宇宙本源法则在特定空间位置的高密度凝聚体，具备自我维持与校准能力。</td></tr><tr><td>2</td><td>锚点共生文明</td><td>以锚点机制为技术基础、以共生进化为核心理念的文明形态。反对掠夺式修炼体系，主张将命运与进化的选择权交还给众生，实现多劳多得、自生自长、人人有路、万族共进。</td></tr><tr><td>3</td><td>衡元宙</td><td>&quot;万灵衡锚本源宙&quot;的简称，是锚点共生文明所栖居与治理的宇宙全域。由物质位面、能量层、意识域与法则网络四个层级共同构成的复合存在体。</td></tr><tr><td>4</td><td>万灵衡锚本源宙</td><td>衡元宙的全称。&quot;万灵&quot;指代一切具备感知与进化潜能的生命形态，&quot;衡锚&quot;指代维系宇宙平衡的锚点机制，&quot;本源宙&quot;强调以本源法则为根基、以共生进化为方向的本质属性。</td></tr><tr><td>5</td><td>共生</td><td>锚点共生文明的核心理念之一，指不同生命个体、种族与文明之间通过互利协作实现共同进化，而非以牺牲他人为代价的掠夺式进化。</td></tr><tr><td>6</td><td>掠夺式修炼体系</td><td>以吞噬弱者能量、气运甚至本源来实现自身进化的修炼方式。锚点共生文明坚决反对的体系类型，被认为是导致宇宙熵增加速、文明断层频发的根源。</td></tr><tr><td>7</td><td>三百套本源修炼体系</td><td>从宇宙本源法则中直接提炼、经过锚点验证的正统修炼路径，共三百套，分为本源推演类、生命循环类、空间法理类、意识升维类、共生网络类、应用工程类六大类，每类五十套。</td></tr><tr><td>8</td><td>本源三基</td><td>三百套体系中的前三套基础体系——推演迭代体系（第1套）、生命循环体系（第2套）、空间法理调度体系（第3套），是所有其他体系的修炼基础。</td></tr><tr><td>9</td><td>推演迭代体系</td><td>第1套本源修炼体系，以百倍修炼推演增幅为核心特征，借助倍增果实的技术化应用将推演能力提升百倍，强调通过推演、验证、迭代优化修炼路径。</td></tr><tr><td>10</td><td>生命循环体系</td><td>第2套本源修炼体系，以生命能量的良性循环为核心，强调修炼者自身与环境之间的能量交换必须是循环式而非掠夺式的。</td></tr><tr><td>11</td><td>空间法理调度体系</td><td>第3套本源修炼体系，以空间法则的理解与调度为核心，是跨位面交互、隔离空间构建、复制镜技术等重要应用的修炼基础。</td></tr><tr><td>12</td><td>倍增果实</td><td>源自海贼王世界的倍增果实，在衡元宙中被技术化应用，能够将修炼者的推演能力提升百倍，是推演迭代体系的核心辅助工具。开局buff之一。</td></tr><tr><td>13</td><td>联产承包机制</td><td>锚点共生文明的资源分配机制，将宇宙修炼资源以&quot;承包&quot;的方式分配给个体或群体，承包者通过劳动与贡献获得资源使用权，实现多劳多得。</td></tr><tr><td>14</td><td>20%激活战略</td><td>锚点共生文明的阶段性战略目标，前期激活全宇宙20%的众生成为位面至高强者，以此为骨干带动剩余80%众生的共同进化。</td></tr><tr><td>15</td><td>位面至高强者</td><td>修炼达到极高境界、能够独力维系一个位面法则稳定的强者。是20%激活战略的目标培养对象，也是锚点网络的重要维护力量。</td></tr><tr><td>16</td><td>法则网络</td><td>衡元宙结构的第四层级，是宇宙本源法则的运行底层与锚点的根基层。法则网络贯穿整个宇宙，是一切法则操作（包括空间调度、时间回溯、能量转化）的技术基础。</td></tr><tr><td>17</td><td>位面</td><td>由一组相对稳定的法则集合所界定的、具备独立时空连续性的存在区域。每个位面拥有独特的物理常数、能量密度、时间流速与意识活跃度。</td></tr><tr><td>18</td><td>法则壁垒</td><td>分隔相邻位面的法则屏障，其强度取决于相邻位面之间法则参数的差异程度。位面穿梭需要克服法则壁垒。</td></tr><tr><td>19</td><td>法则指纹</td><td>每个位面核心法则参数经哈希运算生成的唯一标识，长度为128位，是位面坐标体系的核心参数之一。</td></tr><tr><td>20</td><td>先观测后有限干涉</td><td>时间回溯与跨位面考古的首要操作原则，要求任何回溯或考古必须先完成纯观测阶段，确认无重大风险后方可进行有限度的干涉。</td></tr><tr><td>21</td><td>复制镜</td><td>基于空间法理法则的高精度复制装置，能够在不接触原物的前提下对目标区域进行1:1完整复制，是异地考古方案的核心设备。</td></tr><tr><td>22</td><td>隔离空间</td><td>通过空间法理调度技术构建的独立法则区域，用于承载考古副本并作为考古人员工作场所，与外部宇宙由法则壁垒完全分隔。</td></tr><tr><td>23</td><td>仅回传知识</td><td>考古协议的核心原则，指考古过程中从目标对象获取的只能是抽象的知识与信息，不得回传任何物质、能量或生命体。</td></tr><tr><td>24</td><td>信息纯化</td><td>将原始信息中携带的来源位面法则印记彻底剥离、只保留纯粹语义内容的技术过程，是确保回传知识安全性的关键环节。</td></tr><tr><td>25</td><td>时间悖论</td><td>时间回溯操作中因干涉行为导致因果逻辑出现自相矛盾的现象，包括弑祖悖论、信息悖论、本体悖论与事件悖论四大类。</td></tr><tr><td>26</td><td>因果链</td><td>事件之间前因后果的连续线性结构，是时间法则的核心概念。时间回溯操作的核心风险就是对因果链的扰动。</td></tr><tr><td>27</td><td>共生宪法</td><td>锚点共生文明的根本大法，具有最高法律效力，确立了反掠夺、倡共生的文明底色与七大宪法基本原则。</td></tr><tr><td>28</td><td>万族平等</td><td>共生宪法七大基本原则之一，指一切生命形态无论种族、修为、出身，在法律面前一律平等。</td></tr><tr><td>29</td><td>奇特生命</td><td>不符合常规生命定义、具备特殊存在形态的生命形式，需要按照三类标准化处置流程进行识别与管理。</td></tr><tr><td>30</td><td>奇异能量</td><td>不符合常规能量分类、具备特殊属性与行为模式的能量形式，需要按照三类标准化处置流程进行分类与管控。</td></tr><tr><td>31</td><td>黑暗置换体</td><td>一种特殊的生命形态，涉及双魂共存的伦理问题，需按照双魂伦理准则与四类分支处置规则进行管理。</td></tr><tr><td>32</td><td>双魂伦理</td><td>针对黑暗置换体中两个灵魂共存状态的伦理准则，核心是尊重两个灵魂的各自权利，禁止强制融合或消灭其中一方。</td></tr><tr><td>33</td><td>五种共生文明分型</td><td>基于现实世界文明特征划分的五种共生社会类型：东亚集约型、北欧福利型、北美多元型、欧洲大陆社会型、发展中赶超型。</td></tr><tr><td>34</td><td>四阶段升维路径</td><td>衡元宙宇宙整体升维的四阶段路线：现实筑基→科技赋能→意识进化→星际共生。</td></tr><tr><td>35</td><td>现实为基</td><td>锚点共生文明的根本立场之一，指现实世界是唯一真实世界，小说世界是虚假思想实验，虚构不足用现实补充，现实没有的基于规律升级创造。</td></tr><tr><td>36</td><td>共生度</td><td>评估一个文明或个体与共生网络融合程度的量化指标，涵盖资源共享度、协作频率、利他行为比例等多个维度。</td></tr><tr><td>37</td><td>锚点议事会</td><td>锚点共生文明的最高权力机构，由万族代表按比例组成，行使立法权与重大事项决定权。</td></tr><tr><td>38</td><td>共生执行委员会</td><td>锚点共生文明的最高行政机构，负责宪法与法律的执行、日常治理。</td></tr><tr><td>39</td><td>共生法院</td><td>锚点共生文明的最高司法机构，独立行使审判权，负责违宪审查与重大案件审理。</td></tr><tr><td>40</td><td>位面管理局</td><td>锚点议事会下属的专门机构，负责位面坐标总库维护、穿梭许可审批、跨位面考古管理等事务。</td></tr><tr><td>41</td><td>六大顶层公理</td><td>衡元宙全部设定的最高法理底座，由反掠夺主义公理、万族共和公理、集体升维公理、因果自律公理、法则优先公理、众生全员无限均等法则共同构成；任何文档与扩容不得与之冲突。</td></tr><tr><td>42</td><td>反掠夺主义公理</td><td>六大顶层公理之一：开发增量，不消耗存量；不以杀伐掠夺为进化路径；大道全层级公开，无私藏、无垄断。</td></tr><tr><td>43</td><td>万族共和公理</td><td>六大顶层公理之一：一切生灵拥有平等进化资格；万族99%全覆盖；打破强者对知识与大道的垄断。</td></tr><tr><td>44</td><td>集体升维公理</td><td>六大顶层公理之一：强者不独自飞升，抬着万族一起向前进化；万族共和共建、阿赖耶全网共享；杜绝大材小用。</td></tr><tr><td>45</td><td>因果自律公理</td><td>六大顶层公理之一：跨位面操作严格报备，先观测后有限干涉，只回传知识不扰动因果；彻底根除文明倒退、历史倒车、轮回收割、阶层固化。</td></tr><tr><td>46</td><td>法则优先公理</td><td>六大顶层公理之五：法则先行，永不吃书、永不烂尾；设定自洽高于剧情便利，剧情不得绑架设定；世界观可无限扩容而不崩坏。</td></tr><tr><td>46.5</td><td>众生全员无限均等法则</td><td>六大顶层公理之六（新增）：锚点共生文明内，所有生灵自带基础无限之力；佛系/懒狗保有保底基础无限，不会被时代淘汰；卷王、少年至尊可叠加更多更高层级的无限。</td></tr><tr><td>47</td><td>设定自洽度</td><td>诸天对标评判维度之一，衡量一个IP世界观内部设定的逻辑一致性与法则稳定性；衡元宙因法则先行而设定自洽度趋近满分。</td></tr><tr><td>48</td><td>吃书烂尾风险</td><td>诸天对标评判维度之一，衡量长篇IP因剧情绑架设定而推翻前期设定、战力崩坏、仓促收尾的概率；斗罗、遮天等传统长篇IP在此维度风险显著。</td></tr><tr><td>49</td><td>剧情绑架设定</td><td>传统长篇IP的通病：为推动剧情便利而临时修改、推翻或遗忘前期设定，导致法则网络撕裂、世界观崩坏；是吃书烂尾的根源。</td></tr><tr><td>50</td><td>主角唯一性依赖度</td><td>诸天对标统一评判标准，分五级：极高（独木式文明，如古尘沙）→高（恩赐式文明，如唐罗）→中（寡头式文明，如叶凡）→极低（网络式文明，衡元宙）。</td></tr><tr><td>51</td><td>基础无限之力</td><td>公理六核心概念：所有生灵自带的保底无限本源，佛系/懒狗亦保有，不会被时代淘汰；是掠夺失去意义的本源依据。</td></tr><tr><td>52</td><td>有限资源掠夺内卷</td><td>诸天对标评判维度：旧宇宙资源与大道有限，必然导致掠夺内卷；与衡元宙无限本源形成对照。</td></tr></tbody></table><h2 id="三、术语使用规范" tabindex="-1">三、术语使用规范 <a class="header-anchor" href="#三、术语使用规范" aria-label="Permalink to &quot;三、术语使用规范&quot;">​</a></h2><ol><li>本词典收录的术语为标准术语，全部文档应优先使用本词典中的标准表述。</li><li>同一概念在不同文档中必须使用相同的术语，不得随意更换同义词。</li><li>新设定中产生的新术语，应及时提交术语委员会审核，审核通过后增补入本词典。</li><li>术语的定义如发生修订，以本词典最新版本为准，同时须在文档版本说明中记录修订内容。</li><li>引用术语时，首次出现可使用全称，后续可使用简称，但须确保上下文含义明确。</li></ol><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>术语词典是整个设定体系的语言基石。统一的术语体系确保了百份文档之间的概念一致性，使读者能够在不同模块之间无缝切换而不产生理解歧义。随着设定体系的不断丰富与完善，本词典将持续更新，始终作为全部文档的术语权威来源。</p><h2 id="关联文档" tabindex="-1">关联文档 <a class="header-anchor" href="#关联文档" aria-label="Permalink to &quot;关联文档&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览</li><li>02-锚点本源定义与本质</li><li>99-文档版本与维护说明</li></ul>',12)])])}const b=d(o,[["render",l]]);export{c as __pageData,b as default};
